<?php
namespace App\Filament\Admin\Resources\DataSubjectRequests\Pages;use App\Application\Privacy\DataSubjectRequestService;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\DataSubjectRequests\DataSubjectRequestResource;use Filament\Actions\Action;use Filament\Forms\Components\{Select,Textarea};use Filament\Resources\Pages\ViewRecord;final class ViewDataSubjectRequest extends ViewRecord{protected static string$resource=DataSubjectRequestResource::class;protected function getHeaderActions():array{return[Action::make('verify')->visible(fn()=>$this->record->status==='RECEIVED')->schema([Textarea::make('identity_evidence')->required()->minLength(20)])->action(function(array$d){if(ServiceValidation::run(fn()=>app(DataSubjectRequestService::class)->verify($this->record,$d['identity_evidence'],auth()->user()))===null)return;}),Action::make('resolve')->visible(fn()=>in_array($this->record->status,['VERIFIED','IN_PROGRESS'],true))->schema([Select::make('decision')->options(['FULFIL'=>'Fulfil','DENIED'=>'Deny','EXEMPT'=>'Legal exemption'])->required(),Textarea::make('notes')->required()])->action(function(array$d){if(ServiceValidation::run(fn()=>app(DataSubjectRequestService::class)->resolve($this->record,$d['decision'],$d['notes'],auth()->user()))===null)return;})];}}
